#[test]
fn unreachable_definition_used_in_entry_is_rejected() {
    let text = [
        "OpCapability Shader",
        "OpMemoryModel Logical GLSL450",
        "%void = OpTypeVoid",
        "%int = OpTypeInt 32 1",
        "%fn = OpTypeFunction %int",
        "%one = OpConstant %int 1",
        "%main = OpFunction %int None %fn",
        "%entry = OpLabel",
        "OpReturnValue %dead",
        "%deadblock = OpLabel",
        "%dead = OpIAdd %int %one %one",
        "OpReturnValue %dead",
        "OpFunctionEnd",
    ]
    .join("\n");
    let binary = assemble_text(&text).expect("assemble");
    let err = binary
        .as_slice()
        .validate(TargetEnv::Universal1_6)
        .expect_err("uses of values defined only in unreachable blocks must be rejected");
    // Value from unreachable block doesn't dominate the use
    assert!(matches!(err, ValidationError::ValueNotDominated { .. }));
}
#[test]
fn operand_id_must_be_defined_globally() {
    let text = [
        "OpCapability Shader",
        "OpMemoryModel Logical GLSL450",
        "%void = OpTypeVoid",
        "%ptr = OpTypePointer Function %missing",
        "%fn = OpTypeFunction %void",
        "%main = OpFunction %void None %fn",
        "%entry = OpLabel",
        "OpReturn",
        "OpFunctionEnd",
    ]
    .join("\n");
    let binary = assemble_text(&text).expect("assemble");
    let err = binary
        .as_slice()
        .validate(TargetEnv::Universal1_6)
        .expect_err("global operands must reference defined ids");
    assert!(matches!(
        err,
        ValidationError::UndefinedId { function: None, .. }
    ));
}
#[test]
fn operand_id_must_be_defined_in_function_scope() {
    let text = [
        "OpCapability Shader",
        "OpMemoryModel Logical GLSL450",
        "%void = OpTypeVoid",
        "%int = OpTypeInt 32 1",
        "%fn = OpTypeFunction %int",
        "%main = OpFunction %int None %fn",
        "%entry = OpLabel",
        "OpBranch %merge",
        "%merge = OpLabel",
        "%phi = OpPhi %int %undef %entry",
        "OpReturnValue %phi",
        "OpFunctionEnd",
    ]
    .join("\n");
    let binary = assemble_text(&text).expect("assemble");
    let err = binary
        .as_slice()
        .validate(TargetEnv::Universal1_6)
        .expect_err("operands inside functions must reference defined ids");
    assert!(matches!(
        err,
        ValidationError::UndefinedId {
            function: Some(_),
            ..
        }
    ));
}
