fn module_with_extension(extension: &str) -> String {
    module_with_extension_custom(
        extension,
        "OpCapability Shader",
        "OpMemoryModel Logical GLSL450",
    )
}
fn opencl_module_with_extension(extension: &str) -> String {
    // Note: OpenCL requires Physical32/Physical64 addressing model
    [
        "OpCapability Kernel",
        "OpCapability Addresses",
        &format!("OpExtension \"{extension}\""),
        "OpMemoryModel Physical64 OpenCL",
        "%void = OpTypeVoid",
        "%fn = OpTypeFunction %void",
        "%main = OpFunction %void None %fn",
        "%entry = OpLabel",
        "OpReturn",
        "OpFunctionEnd",
    ]
    .join("\n")
}
fn module_with_extension_custom(extension: &str, capability: &str, memory_model: &str) -> String {
    [
        capability,
        &format!("OpExtension \"{extension}\""),
        memory_model,
        "%void = OpTypeVoid",
        "%fn = OpTypeFunction %void",
        "%main = OpFunction %void None %fn",
        "%entry = OpLabel",
        "OpReturn",
        "OpFunctionEnd",
    ]
    .join("\n")
}
